-- Base "sucia" para probar V13/V14 (DF-DATA-001 / DF-BUG-009): mismo esquema
-- pre-Flyway que esquema-antes-de-flyway.sql, pero con productos como los
-- que encontro la auditoria real (tipo_cantidad nulo, stock decimal en lo
-- que deberia ser por unidad, codigo_barras vacio).
--
-- No se toca cuando cambia el modelo: es una foto de un estado de datos, y
-- su valor es probar que V13/V14 lo dejan bien sin perder nada.

create table categoria (id bigint generated by default as identity, descripcion varchar(255), nombre varchar(255), primary key (id));
create table compra (fecha_anulacion timestamp(6), fecha_hora timestamp(6), id bigint generated by default as identity, anulada_por varchar(255), proveedor varchar(255), usuario varchar(255), estado enum ('ACTIVA','ANULADA'), primary key (id));
create table configuracion (ganancia_por_defecto float(53), umbral_stock_bajo float(53), id bigint not null, version bigint, nombre_negocio varchar(255), primary key (id));
create table detalle_compra (cantidad float(53) not null, precio_costo float(53) not null, precio_costo_anterior float(53), subtotal float(53) not null, compra_id bigint, id bigint generated by default as identity, producto_id bigint, primary key (id));
create table detalle_venta (cantidad float(53) not null, precio_costo float(53) not null, precio_unitario float(53) not null, subtotal float(53) not null, id bigint generated by default as identity, producto_id bigint, venta_id bigint, primary key (id));
create table producto (activo boolean not null, fraccion_minima float(53), porcentaje_ganancia float(53) not null, precio_costo float(53) not null, precio_venta float(53) not null, stock float(53) not null, unidades_por_paquete integer, categoria_id bigint, id bigint generated by default as identity, version bigint, codigo_barras varchar(255), imagen_url varchar(255), nombre varchar(255), proveedor varchar(255), tipo_cantidad varchar(255), unidad_medida varchar(255), primary key (id));
create table promocion (activo boolean not null, cantidad_lleva integer not null, cantidad_paga integer not null, id bigint generated by default as identity, producto_id bigint, primary key (id));
create table usuario (id bigint generated by default as identity, nombre varchar(255), password varchar(255), rol varchar(255), username varchar(255) unique, primary key (id));
create table venta (total float(53) not null, fecha_anulacion timestamp(6), fecha_hora timestamp(6), id bigint generated by default as identity, anulada_por varchar(255), usuario varchar(255), estado enum ('ACTIVA','ANULADA') not null, primary key (id));

-- id 1: el caso "chupetin" real -- tipo nulo Y stock ya arrastraba decimal
-- (0,5 vendido de a poco por el bug). tipo_cantidad NULL, codigo_barras NULL.
insert into producto (id, activo, nombre, porcentaje_ganancia, precio_costo, precio_venta, stock, version)
values (1, true, 'Chupetin surtido', 50.0, 10.0, 15.0, 38.5, 1);

-- id 2: tipo nulo pero stock ya entero -- no tiene que tocarse el stock,
-- solo completarse el tipo. codigo_barras vacio (no NULL): tiene que
-- normalizarse a NULL para no romper el indice unico.
insert into producto (id, activo, nombre, porcentaje_ganancia, precio_costo, precio_venta, stock, codigo_barras, version)
values (2, true, 'Obleas surtidas', 50.0, 5.0, 8.0, 12.0, '', 1);

-- id 3: ya viene coherente como PESO/kg con stock decimal real -- V13 no
-- tiene que tocarlo (el CEIL es solo para tipo_cantidad = 'UNIDAD').
insert into producto (id, activo, nombre, porcentaje_ganancia, precio_costo, precio_venta, stock, tipo_cantidad, unidad_medida, codigo_barras, version)
values (3, true, 'Fiambre surtido', 80.0, 1000.0, 1800.0, 2.75, 'PESO', 'kg', '7791112223334', 1);

-- id 4: producto dado de baja (borrado logico) con su propio codigo -- sirve
-- para el test de unicidad que involucra inactivos.
insert into producto (id, activo, nombre, porcentaje_ganancia, precio_costo, precio_venta, stock, tipo_cantidad, unidad_medida, codigo_barras, version)
values (4, false, 'Producto borrado', 50.0, 100.0, 150.0, 3.0, 'UNIDAD', 'u', '7795556667778', 1);
